-- 매거진 창간호 초안 본문 복구 (2026-08-13)
-- 서버 액션 직렬화 사고로 사진 5장의 주소와 소제목 10개의 레벨이 날아간 것을 되돌린다.
-- 사진 순서 = Storage 업로드 시각 순(본문 위→아래). 반영 후 화면에서 순서를 확인해 주세요.
update magazine_articles
   set body = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"8월 9일(토) 오전 10시, 일산 두더지요가원에서 ","type":"text"},{"text":"캔버스가든 × 두더지요가원","type":"text","marks":[{"type":"bold"}]},{"text":"의 콜라보가 열렸어요. 이번 콜라보에서는 점토로 각자의 요가 자세를 ","type":"text"},{"text":"토우(土偶) 오브제","type":"text","marks":[{"type":"bold"}]},{"text":"로 만들고, 완성한 토우의 자세를 바탕으로 ","type":"text"},{"text":"요가 수업","type":"text","marks":[{"type":"bold"}]},{"text":"을 진행했어요. ","type":"text"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"헌 옷, 자투리천 등을 활용해 ''나다움''을 찾아가는 수선조형 스튜디오 캔버스가든(캔가), 요가를 통해 자신의 몸과 마음을 탐색해가는 두더지요가원. 두 브랜드가 어떻게 만나 하나의 콜라보를 만들었는지, 그날의 과정을 따라가 봤어요.","type":"text"},{"type":"hardBreak"}]},{"type":"paragraph"},{"type":"image","attrs":{"src":"https://yfvesialziwdacsjlzph.supabase.co/storage/v1/object/public/maker-photos/magazine/p/31017b55-6e13-43d6-8ef5-b6464a487a4f.jpg","alt":"","title":null,"caption":"","width":null}},{"type":"heading","content":[{"text":"시작은 \"귀여움과 귀여움\"이었어요","type":"text"}],"attrs":{"level":3}},{"type":"paragraph","content":[{"text":"두 브랜드가 처음 연결된 계기는 의외로 단순했어요. 캔버스가든의 가든 작가님은 평소 두더지요가원을 보며 ","type":"text"},{"text":"\"두더지라니.. 너무 귀여운데? 내가 만드는 토우도 진짜 귀여운데..\"","type":"text","marks":[{"type":"bold"}]},{"text":"라는 생각을 했다고 해요. 두더지라는 이름과 상징이 가진 귀여움, 손가락만 한 흙 인형이 가진 귀여움.  다르고도 비슷한 두 객체의 만남. ","type":"text"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"그런데 콜라보 이야기를 나누다 보니 귀여움 말고도 재미있는 접점들도 보였어요. ","type":"text"},{"text":"토우는 사람의 몸을 밖에서 들여다보며 만드는 일이고, 요가는 내 몸을 안에서 직접 느끼는 일이거든요. ","type":"text","marks":[{"type":"bold"}]},{"text":"토우를 만들 때는 팔이 어디로 뻗어 있는지, 다리가 어떤 각도로 접혀 있는지를 눈으로 보고 손으로 표현하지만 반대로 요가에서는 같은 자세를 직접 해보며 어떤 부분이 당겨지고, 어디에 힘이 들어가는지를 몸으로 알아차리죠. 결국 이번 콜라보는 ","type":"text"},{"text":"하나의 몸을 바깥에서 바라보는 일과 안에서 경험하는 일을 연속적으로 구성해본 셈","type":"text","marks":[{"type":"bold"}]},{"text":"이었어요.","type":"text"},{"type":"hardBreak"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"\"토우는 오래전 숭배의 대상이기도, 누군가의 손장난이기도 했던 작은 점토 인형입니다. 정교하지 않아도, 손자국이 남아도 괜찮습니다.\"","type":"text"}]},{"type":"paragraph","content":[{"text":"— 워크숍 모집 글에서","type":"text"}]}]},{"type":"horizontalRule"},{"type":"heading","content":[{"text":"철사가 귀여운 토우가 되기까지","type":"text"}],"attrs":{"level":3}},{"type":"paragraph","content":[{"text":"오전 10시, 토우 만들기부터 시작했어요.","type":"text"}]},{"type":"paragraph"},{"type":"image","attrs":{"src":"https://yfvesialziwdacsjlzph.supabase.co/storage/v1/object/public/maker-photos/magazine/p/7f0c1078-d971-431b-ac54-f13132947a36.jpg","alt":"","title":null,"caption":"","width":null}},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"참가자들은 동그랗게 둘러앉아 철사를 구부려 뼈대부터 만들었어요. 머리 하나, 팔 둘, 다리 둘. 구부리고 조이고, 다시 펴고. 처음에는 토우라는 오브제가 낯설어서인지 서로의 작업을 살펴보며 조심스럽게 시작했어요. 그러다 철사가 조금씩 사람의 형태를 갖추기 시작하면서 분위기도 달라졌습니다. ","type":"text"},{"text":"각자가 마음에 둔 요가 자세가 조금씩 모습을 드러내기 시작한 거예요.","type":"text","marks":[{"type":"bold"}]},{"type":"hardBreak"},{"type":"hardBreak"},{"text":"누군가는 한쪽 다리로 서는 자세를, 누군가는 두 팔을 크게 뻗은 자세를 골랐어요. 다른 참가자들의 토우를 구경하다가 마음을 바꾸기도 하고, 철사를 다시 구부리기도 했고요. 아직 점토를 붙이지도 않았는데, 벌써 각자의 몸이 조금씩 드러나기 시작했어요.","type":"text"}]},{"type":"paragraph"},{"type":"heading","content":[{"text":"너무 두꺼우면 안 마르고, 너무 얇으면 갈라져요","type":"text"}],"attrs":{"level":3}},{"type":"paragraph","content":[{"text":"철사 뼈대가 완성되면 그 위에 지점토를 붙여 몸의 형태를 만들어갑니다.","type":"text"}]},{"type":"paragraph","content":[{"text":"여기서부터는 가든 작가님의 구체적인 안내가 이어졌어요. 점토를 너무 두껍게 붙이면 잘 마르지 않고, 너무 얇으면 마르면서 갈라지거나 떨어질 수 있다고 해요. 그런데 같은 설명을 듣고 만들어도 결과물은 꽤 달랐습니다.","type":"text"}]},{"type":"paragraph"},{"type":"image","attrs":{"src":"https://yfvesialziwdacsjlzph.supabase.co/storage/v1/object/public/maker-photos/magazine/p/55977a54-7d78-4dcc-af8c-308645d4dd98.jpg","alt":"","title":null,"caption":"","width":null}},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"어떤 사람은 아주 얇고 작은 토우를 만들었고, 어떤 사람은 점토를 두툼하게 붙여 묵직한 토우를 만들었어요. 같은 재료와 같은 방법으로 시작했지만, 만들어지는 모습은 하나같이 달랐습니다.","type":"text"}]},{"type":"paragraph","content":[{"text":"손으로 점토를 붙이고 조각칼로 표면을 다듬는 시간이 한참 이어졌어요.","type":"text"}]},{"type":"paragraph"},{"type":"image","attrs":{"src":"https://yfvesialziwdacsjlzph.supabase.co/storage/v1/object/public/maker-photos/magazine/p/3764dea6-f129-45f4-9a61-ef4991a84952.jpg","alt":"","title":null,"caption":"","width":null}},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"그리고 이날은 두더지요가원의 ","type":"text"},{"text":"지예 원장님도 잠시 선생님의 자리를 내려놓고 참가자로 함께 앉아 있었습니다.","type":"text","marks":[{"type":"bold"}]},{"text":" 한 시간 뒤에는 다시 요가를 가르치는 원장님으로 돌아가셔야했지만, 천진한 웃음과 함께 토우 만들기를 적극적으로 함께했어요.","type":"text"}]},{"type":"paragraph"},{"type":"horizontalRule"},{"type":"heading","content":[{"text":"이날의 숨은 공신, 남편 두 분","type":"text"}],"attrs":{"level":3}},{"type":"paragraph","content":[{"text":"형태가 완성된 토우들은 옆 테이블의 히팅건 앞으로 이동했습니다.","type":"text"}]},{"type":"paragraph","content":[{"text":"채색을 하려면 점토가 충분히 말라야 했기 때문이에요. 그래서 이날 한쪽에서는 토우를 만드는 작업이, 다른 한쪽에서는 토우를 말리는 작업이 동시에 진행됐습니다. 그리고 이 건조 코너를 계속 지킨 사람이 있었어요.","type":"text"}]},{"type":"paragraph"},{"type":"image","attrs":{"src":"https://yfvesialziwdacsjlzph.supabase.co/storage/v1/object/public/maker-photos/magazine/p/b6b1b159-641d-4d9c-95e4-a1eb1ed3d4b0.jpg","alt":"","title":null,"caption":"","width":null}},{"type":"paragraph"},{"type":"paragraph","content":[{"text":"가든 작가님의 남편분과 지예 원장님의 남편분.","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"두 분은 워크숍 내내 히팅건으로 토우를 하나씩 말려주셨어요. 겉으로 보기에는 작은 과정처럼 보이지만, 이번 콜라보에서는 꽤 중요한 일이었습니다.","type":"text"}]},{"type":"paragraph","content":[{"text":"실제로 참가 인원을 열 명으로 제한한 이유 중 하나도 건조 시간이었어요. 토우를 충분히 말리려면 계속 사람이 붙어 있어야 하고, 하나씩 꼼꼼하게 건조해야 했기 때문이라고 해요.","type":"text"}]},{"type":"paragraph","content":[{"text":"이날의 짝꿍님들 덕분에 콜라보는 순조롭게 다음 순서로 넘어갈 수 있었어요.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","content":[{"text":"손바닥 위에 있던 자세가, 요가 수업의 자세로","type":"text"}],"attrs":{"level":3}},{"type":"paragraph","content":[{"text":"토우가 마르는 동안 지예 원장님의 요가 수업이 시작됐어요.","type":"text"}]},{"type":"paragraph","content":[{"text":"이번 요가 수업은 조금 특별했습니다. ","type":"text"},{"text":"참가자들이 직접 만든 토우의 자세를 바탕으로 수업을 구성했거든요.","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"양팔과 양다리로 스트레칭 하는 자세부터, 양 팔로만 바닥에서 버텨보는 자세까지. 지예 원장님은 토우로 빚어진 자세를 금세 요가 클래스 내용으로 적용해 참여자분들을 매트 위에서 리드해주셨어요.","type":"text"}]},{"type":"paragraph","content":[{"text":"토우를 만들 때는 몸을 바깥에서 바라봅니다. 팔의 위치와 다리의 각도를 눈으로 확인하고 손으로 만들어내죠. 손끝에서는 쉽게 원하는 자세를 만들어볼 수 있어요. 하지만 같은 자세를 내 몸으로 직접 해보면 이야기가 달라져요.","type":"text"}]},{"type":"paragraph","content":[{"text":"어디가 당기는지, 어느 쪽에 힘이 들어가는지, 내가 생각했던 것보다 균형을 잡기가 어려운지. 토우를 만들 때는 보이지 않던 것들이 몸을 움직이는 순간 하나씩 드러납니다.","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"몇 분 전까지 손바닥 위에 있던 자세가, 이제는 내 어깨와 내 골반의 일이 되는 순간이었어요.","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"paragraph","content":[{"text":"이번 콜라보가 단순한 ''토우 만들기 + 요가''가 아니었던 이유도 여기에 있었습니다.","type":"text"}]},{"type":"paragraph","content":[{"text":"`<사진 ④>` 요가 수업 — 참가자들이 각자의 토우 자세를 따라 하는 모습","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","content":[{"text":"넘어질 때마다 웃음이 터졌어요","type":"text"}],"attrs":{"level":3}},{"type":"paragraph","content":[{"text":"이날에는 요가원 회원뿐 아니라 요가가 처음인 참가자들도 함께했습니다. 커플 참가자도 두 팀이 있었고요.","type":"text"}]},{"type":"paragraph","content":[{"text":"지예 원장님은 참가자들의 경험과 수준에 맞춰 수업의 난이도를 조절해갔습니다.","type":"text"}]},{"type":"paragraph","content":[{"text":"후반부에는 토우들 가운데 가장 어려운 자세 몇 가지를 골라 다 같이 도전했어요.","type":"text"}]},{"type":"paragraph","content":[{"text":"누군가 자세를 완성하면 박수가 나왔고, 어려운 자세에 계속 도전하다 넘어지는 사람에게는 응원이 이어졌습니다. 넘어지고, 웃고, 다시 일어나고.","type":"text"}]},{"type":"paragraph","content":[{"text":"잘하는 것이 목적이었다면 조금 달랐을지도 모르겠어요. 하지만 이날의 목표는 ","type":"text"},{"text":"각자가 만든 몸을 직접 경험해보는 것","type":"text","marks":[{"type":"bold"}]},{"text":"이었으니까요.","type":"text"}]},{"type":"paragraph","content":[{"text":"마지막에는 모두 매트 위에 누워 사바아사나로 요가를 마무리했습니다.","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","content":[{"text":"이거 MBTI 검사 같은건가요?","type":"text"}],"attrs":{"level":3}},{"type":"paragraph","content":[{"text":"요가가 끝나고 잠시 쉬는 시간이 지나자, 잘 마른 토우들이 요가원 한가운데로 모였습니다. 이 장면에서 이번 콜라보의 또 다른 재미가 드러났어요. 포즈도, 크기도, 두께도 전부 달랐습니다. 같은 재료를 사용했는데도 토우마다 만든 사람의 선택이 꽤 선명하게 보였어요.","type":"text"}]},{"type":"paragraph","content":[{"text":"가든 작가님이 ","type":"text"},{"text":"\"토우에는 만든 사람의 성격이 드러난다\"","type":"text","marks":[{"type":"bold"}]},{"text":"는 이야기를 하자, 한 참가자가 바로 물었습니다.","type":"text"}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"text":"\"이거 MBTI 검사 같은 건가요?\"","type":"text"}]}]},{"type":"paragraph","content":[{"text":"요가원이 한바탕 웃음으로 넘어갔습니다. 그런데 농담처럼 시작한 말이 꽤 재미있는 질문이기도 했어요.","type":"text"}]},{"type":"paragraph","content":[{"text":"실제로 어떤 참가자는 얇고 작은 토우를 만들었고, 어떤 참가자는 두꺼운 점토로 꽤 어려운 자세를 표현했습니다. 만드는 방식도, 선택한 자세도 모두 달랐어요.","type":"text"}]},{"type":"paragraph","content":[{"text":"같은 재료로 만들었지만, 몸을 표현하는 방식에는 각자의 취향과 선택이 자연스럽게 드러났습니다.","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"`<사진 ⑤>` 토우들이 요가원 한가운데 원형으로 모인 모습","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","content":[{"text":"빙수 코치님의 빙수 토우","type":"text"}],"attrs":{"level":3}},{"type":"paragraph","content":[{"text":"마지막은 채색이었어요. 붓을 들자 토우의 개성이 한층 더 선명해졌습니다.","type":"text"}]},{"type":"paragraph","content":[{"text":"빙수를 워낙 좋아해 ''빙수 코치''라는 별명을 가진 참가자는 자신의 토우에 빙수를 만들었고, 누군가는 무지개색을 입혔습니다. 옴(ॐ) 글자를 새긴 토우도 있었고, 커플이 함께 만든 커플 요가 토우도 있었어요.","type":"text"}]},{"type":"paragraph","content":[{"text":"형태를 만드는 과정까지는 비슷했지만, 색을 입히는 순간부터는 완전히 다른 결과물이 됐습니다.","type":"text"}]},{"type":"paragraph","content":[{"text":"그리고 눈코입과 색이 하나씩 더해지면서 토우가 조금씩 ","type":"text"},{"text":"''만든 사람의 것''이 되어가는 과정","type":"text","marks":[{"type":"bold"}]},{"text":"이 보였어요.","type":"text"}]},{"type":"paragraph","content":[{"text":"점토로 만든 작은 사람 하나가 어느새 누군가의 취향과 이야기를 담은 오브제가 된 거죠.","type":"text"}]},{"type":"paragraph","content":[{"text":"`<사진 ⑥>` 채색 클로즈업 — 빙수 토우, 커플 토우, 옴 글자","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","content":[{"text":"철사 한 줄이 완성형의 토우가 되기까지","type":"text"}],"attrs":{"level":3}},{"type":"paragraph","content":[{"text":"오후 1시 무렵, 각자의 토우를 손에 들고 단체 사진을 찍으며 워크숍이 끝났습니다.","type":"text"}]},{"type":"paragraph","content":[{"text":"세 시간 전만 해도 테이블 위에는 철사 몇 가닥과 점토가 놓여 있었어요. 그런데 이제는 그 재료들이 각자 다른 자세를 가진 작은 사람으로 서 있었습니다.","type":"text"}]},{"type":"paragraph","content":[{"text":"이번 콜라보에는 각기 다른 열 명의 참가자가 함께했어요. 아마 이런 구성이 이번 콜라보를 가장 잘 보여주는 모습일 거예요. 요가원 회원, 캔버스가든의 지인, 그리고 근처에 사는 로컬 주민까지 서로 다른 사람들이 한자리에 모였고, 각자가 만든 토우로서 같은 경험을 다르게 표현해보는 시간.","type":"text"}]},{"type":"paragraph","content":[{"text":"`<사진 ⑦>` 각자의 토우를 들고 찍은 단체 사진","type":"text"}]},{"type":"horizontalRule"},{"type":"heading","content":[{"text":"귀여움에서 시작해, 몸을 다시 바라보는 일까지","type":"text"}],"attrs":{"level":3}},{"type":"paragraph","content":[{"text":"처음 두 브랜드의 만남은 단순했습니다.","type":"text"}]},{"type":"paragraph","content":[{"text":"\"둘 다 귀엽잖아요.\"","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"두더지라는 이름에서 느껴지는 귀여움과 작은 토우의 귀여움에서 시작한 만남이었어요. 그런데 하루를 따라가 보니 귀여움만으로 설명하기에는 조금 더 재미있는 연결이 있었습니다.","type":"text"}]},{"type":"paragraph","content":[{"text":"캔버스가든에서는 몸을 ","type":"text"},{"text":"밖에서 바라보며","type":"text","marks":[{"type":"bold"}]},{"text":" 하나의 형태로 만들었고, 두더지요가원에서는 그 형태를 ","type":"text"},{"text":"내 몸 안에서 직접 경험했습니다.","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"토우만 만들었다면 작은 오브제를 만드는 워크숍으로 끝났을 거예요. 요가만 했다면 또 하나의 요가 수업이었겠죠.","type":"text"}]},{"type":"paragraph","content":[{"text":"하지만 이번에는 ","type":"text"},{"text":"토우를 만드는 일이 요가의 재료가 되고, 요가를 하는 일이 다시 토우를 바라보는 방식이 되었습니다.","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"각자 하던 일을 나란히 놓은 게 아니라, 서로의 활동이 다음 활동의 이유가 된 거예요.","type":"text"}]},{"type":"paragraph","content":[{"text":"어쩌면 콜라보의 재미는 바로 이런 데 있는지도 모르겠습니다.","type":"text"}]},{"type":"paragraph","content":[{"text":"둘이 만나기 전에는 없었던 경험이, 만나고 나서 하나 더 생기는 것.","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"이번 캔버스가든 × 두더지요가원의 콜라보에서는 그게 ''","type":"text"},{"text":"몸을 밖에서 만들고, 안에서 느껴보는 하루","type":"text","marks":[{"type":"bold"}]},{"text":"''였습니다.","type":"text"}]}]}'::jsonb
 where slug = 'canvasgarden-x-moleyoga-clay-workshop';
